sys_script_include.script:
var AttendeeUtils = Class.create();
AttendeeUtils.prototype = {
    initialize: function () {
        this._attendeeTable = 'x_1610434_event_0_attendee';
    },

    isAttendeeRegistered: function (_attendeeId) {
        var _attendeeGR = new GlideRecordSecure(this._attendeeTable);
        _attendeeGR.addQuery('sys_id', _attendeeId);
        _attendeeGR.query();
        return _attendeeGR.hasNext();
    },

    getAttendeeDetailsById: function (_attendeeId) {
        var _attendeeGR = new GlideRecordSecure(this._attendeeTable);
        _attendeeGR.addQuery('sys_id', _attendeeId);
        _attendeeGR.query();
        if (_attendeeGR.next()) {
            return this._mapAttendeeFields(_attendeeGR);
        }
        return null;
    },

    getAttendeesByEvent: function (_eventId) {
        var _attendeeList = [];
        var _attendeeGR = new GlideRecordSecure(this._attendeeTable);
        _attendeeGR.addQuery('event_id', _eventId);
        _attendeeGR.query();
        while (_attendeeGR.next()) {
            _attendeeList.push(this._mapAttendeeFields(_attendeeGR));
        }
        return _attendeeList;
    },

	_mapAttendeeFields: function (_attendeeGR) {
        return {
            sysId: _attendeeGR.getUniqueValue(),
            firstName: _attendeeGR.getValue('first_name'),
            lastName: _attendeeGR.getValue('last_name'),
            email: _attendeeGR.getValue('email'),
            contactNumber: _attendeeGR.getValue('contact_number'),
            eventId: _attendeeGR.getValue('event_id')
        };
    },

    type: 'AttendeeUtils'
};
